function Invoke-AuthenticationSmokeTests { param([string]$Username="",[string]$Password="")
    $r=Invoke-ApiRequest "POST" "/api/v1/auth/login" -Body @{username="__invalid_smoke_test_user__";password="__invalid_smoke_test_password__"};if(Assert-StatusCode $r 401 "Invalid credentials are rejected"){Assert-ApiError $r "INVALID_CREDENTIALS" "Invalid login follows the error contract"};$r=Invoke-ApiRequest "GET" "/api/v1/me";if(Assert-StatusCode $r 401 "Anonymous access to /me is rejected"){Assert-ApiError $r "UNAUTHORIZED" "Anonymous access follows the error contract"}
    if(-not$Username-and-not$Password){Write-TestSkipped "Authenticated login test";Write-TestSkipped "Authenticated /me test";Write-TestSkipped "Altered token test";return};if(-not$Username-or-not$Password){Write-TestFailure "Authenticated tests configuration";return}
    $login=Invoke-ApiRequest "POST" "/api/v1/auth/login" -Body @{username=$Username;password=$Password};if(-not(Assert-StatusCode $login 200 "Valid credentials return HTTP 200")){return};$token=(Convert-JsonResponse $login "Login response contains valid JSON").token;if(-not$token){Write-TestFailure "Login response contains a JWT";return};Write-TestSuccess "Login response contains a JWT";$me=Invoke-ApiRequest "GET" "/api/v1/me" -Headers @{Authorization="Bearer $token"};if(Assert-StatusCode $me 200 "Authenticated access to /me succeeds"){if((Convert-JsonResponse $me "/me response contains valid JSON").data.username){Write-TestSuccess "/me response contains user data"}else{Write-TestFailure "/me response contains user data"}};$replacement=if($token.EndsWith("A")){"B"}else{"A"};$altered=$token.Substring(0,$token.Length-1)+$replacement;$r=Invoke-ApiRequest "GET" "/api/v1/me" -Headers @{Authorization="Bearer $altered"};if(Assert-StatusCode $r 401 "Altered JWT is rejected"){Assert-ApiError $r "INVALID_TOKEN" "Altered JWT follows the error contract"}
}
